func TestAbsentMotionShowsTheDefaultAndStaysAbsent(t *testing.T) {
	m := motionModel(t, "")

	if got := fieldNamed(t, motionLabel).Value(m.config); got != "blink (default)" {
		t.Errorf("Value = %q, want %q", got, "blink (default)")
	}
	if !strings.Contains(plainRows(m), "blink (default)") {
		t.Error("the Motion row does not read 'blink (default)'")
	}
	if m.config.App.Motion != "" {
		t.Error("displaying the default wrote it")
	}

	// First arrow: static, written explicitly. Second: blink, explicit, no
	// longer shown as the default.
	next := feed(t, m, testutil.Key("right"))
	if next.config.App.Motion != config.MotionStatic {
		t.Fatalf("first → gave %q, want static", next.config.App.Motion)
	}
	next = feed(t, next, testutil.Key("right"))
	if next.config.App.Motion != config.MotionBlink {
		t.Fatalf("second → gave %q, want an explicit blink", next.config.App.Motion)
	}
	if got := fieldNamed(t, motionLabel).Value(next.config); got != "blink" {
		t.Errorf("explicit blink reads %q, want plain blink", got)
	}
}
// Cycle moves a closed-set field by one step, wrapping. An unrecognised current
// value lands on the first option rather than being preserved: the set is
// closed, so a value outside it is not something to carry forward.
func (f field) Cycle(c *config.Config, step int) {
	if len(f.Options) == 0 {
		return
	}
	p := f.str(c)
	idx := 0
	if *p == "" && f.def != "" {
		idx = slices.Index(f.Options, f.def)
		idx = max(idx, 0)
	}
	for i, opt := range f.Options {
		if opt == *p {
			idx = i
			break
		}
	}
	*p = f.Options[(idx+step+len(f.Options))%len(f.Options)]
}

// Apply writes an edited text or integer value, or refuses it.
//
// Refusing is the whole point (Rule 128 reports it, the config keeps its old
// value): an unparseable number silently coerced to zero is how `trivy_server:
// ":"` reached a config file in the first place.
	f.Toggle(m.config)
	return m, m.persist(saved{})
}

// saved says which settings this write touched that the router has to act on
// rather than merely rebuild views against.
type saved struct {
	theme bool
	// forgeChanged says the session this context holds was opened against
	// something the config no longer describes — a different host, or a
	// different platform. One flag for both, because the consequence is one:
	// the session is stale and the user has to sign in again.
	forgeChanged bool
	// engineChanged says the container engine has to be re-resolved before any
	// rebuilt view asks it for a list.
	engineChanged bool
}

// persist applies the cross-field constraints, saves, and tells the router.
func (m Model) persist(what saved) tea.Cmd {
	if err := config.Save(m.config); err != nil {
		log.Printf("ERROR [configuration] save context %s: %v", m.context, err)
		// Reported through the message rather than set here: Update() owns the
		// model, and this is called from it, but the caller decides the footer.
		return func() tea.Msg { return saveFailedMsg{err} }
	}

	cfg := m.config
	return func() tea.Msg {
		return ConfigSavedMsg{
			Config:        cfg,
			ThemeChanged:  what.theme,
			ForgeChanged:  what.forgeChanged,
			EngineChanged: what.engineChanged,
		}
	}
}

type saveFailedMsg struct{ err error }

